}
/** @return never */
function outMemory(string $name,string $rid): never {
    $res=kicomReadMemoryResource($name);
    if($res===null) out([KCL_PROTOCOL,'ERROR memory','FACT request_id='.kclString($rid),'FACT code="MEMORY_RESOURCE_UNAVAILABLE"','FACT resource='.kclString($name),'END'],503);
    $lines=[KCL_PROTOCOL,'OK memory','FACT request_id='.kclString($rid),'FACT resource='.kclString($name),'FACT bytes='.$res['bytes'],'FACT sha256='.kclString($res['sha256']),'BEGIN_RESOURCE '.$name];
    foreach(preg_split('/\r?\n/',$res['content'])?:[] as $line)$lines[]=$line;
    $lines[]='END_RESOURCE '.$name;$lines[]='END';out($lines);
}
function probeHttps(string $url): array {
