        $result=curl_exec($ch);$httpCode=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);if($result===false)$error=(string)curl_error($ch);curl_close($ch);
    } else {
        $context=stream_context_create(['http'=>['method'=>'HEAD','timeout'=>7,'ignore_errors'=>true,'follow_location'=>0,'user_agent'=>'KiCom/'.KICOM_VERSION.' health probe'],'ssl'=>['verify_peer'=>true,'verify_peer_name'=>true]]);
        $headers=@get_headers($url,true,$context);if(is_array($headers)&&isset($headers[0])&&preg_match('/\s(\d{3})\s/',(string)$headers[0],$m))$httpCode=(int)$m[1];else$error='http_probe_failed';
    }
    $latency=(int)round((microtime(true)-$start)*1000);return ['ok'=>($httpCode>=200&&$httpCode<500&&$error===''),'http_code'=>$httpCode,'latency_ms'=>$latency,'error'=>$error];
}

